insert into public.questions (id, pack_id, theme, type, prompt, unit, answer, items, year, tolerance, subject, source, source_url, perishable, difficulty, status, verified_at, review_due_at, notes)
values
('amour-051', 'classique', 'amour', 'number'::public.question_type, 'Selon la grande enquête Inserm-ANRS « Contexte des sexualités en France » de 2023, quel est l’âge médian au premier rapport des femmes, en hausse pour la première fois depuis les années 1960 ?', 'ans', 18.2, null, false, null, 'csf-premier-rapport', 'Inserm / ANRS-MIE (enquête CSF 2023)', 'https://anrs.fr/wp-content/uploads/2024/11/rapp-csf-web.pdf', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Âge médian 2023 : 18,2 ans (femmes), 17,7 ans (hommes), contre 17,3 ans en 2010. Accepter 18.'),
('amour-052', 'classique', 'amour', 'number'::public.question_type, 'Combien de jours a duré le plus long accouplement connu chez un insecte, observé chez le phasme indien Necroscia sparaxes ?', 'jours', 79, null, false, null, 'phasme-accouplement', 'Psyche (Cambridge Entomological Club, 1978)', 'https://groups.csail.mit.edu/mac/projects/psyche/85/85-395.html', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Article de 1978 : couples restés unis jusqu’à 79 jours, record chez les insectes ; repris par le Smithsonian Magazine.'),
('amour-053', 'classique', 'amour', 'number'::public.question_type, 'Selon le Guinness, combien de millimètres mesure, une fois déroulé, le spermatozoïde de la mouche Drosophila bifurca, le plus long du règne animal ?', 'mm', 63.5, null, false, null, 'spermatozoide-drosophile', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/70671-longest-sperm-animals', false, 3, 'review'::public.question_status, '2026-10-20', null, 'GWR : 6,35 cm. D’autres sources (Univ. de Zurich, PopSci) donnent ≈ 5,8 cm : énoncé attribué au Guinness. Environ 20 fois la taille de la mouche. À relire : sources divergentes ou chiffre contesté.'),
('amour-054', 'classique', 'amour', 'number'::public.question_type, 'Selon une étude parue dans Nature en 2003 (124 couples observés), quel pourcentage d’amoureux penchent la tête vers la droite pour s’embrasser, le côté de loin le plus fréquent ?', '%', 64.5, null, false, null, 'baiser-tete-droite', 'Nature (Güntürkün, 2003)', 'https://www.nature.com/articles/421711a', false, 1, 'published'::public.question_status, '2026-10-20', null, '80 couples sur 124 à droite (64,5 %), 44 à gauche. Accepter 65.'),
('amour-055', 'classique', 'amour', 'number'::public.question_type, 'Selon la plus vaste étude sur le sujet (168 cultures, publiée en 2015), dans quel pourcentage des cultures du monde le baiser amoureux est-il pratiqué ?', '%', 46, null, false, null, 'baiser-cultures', 'American Anthropologist (Jankowiak et al., 2015)', 'https://carta.anthropogeny.org/node/308328', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Baiser amoureux présent dans 46 % des cultures étudiées (minorité) ; absent des données pour 54 %.'),
('amour-056', 'classique', 'amour', 'number'::public.question_type, 'Selon une étude parue dans Science en 2023, de combien d’années environ datent les plus anciennes mentions écrites du baiser amoureux, retrouvées en Mésopotamie ?', 'ans', 4500, null, false, null, 'baiser-mesopotamie', 'Science (Arbøll et Rasmussen, 2023)', 'https://www.science.org/doi/10.1126/science.adf0512', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Tablettes cunéiformes vers 2500 av. J.-C., soit ≈ 4 500 ans ; recule de 1 000 ans la plus ancienne trace connue (Inde, ≈ 1500 av. J.-C.).'),
('amour-057', 'classique', 'amour', 'number'::public.question_type, 'Combien de milliers de papillons du ver à soie le chimiste Adolf Butenandt a-t-il dû utiliser pour isoler le bombykol, la toute première phéromone sexuelle identifiée (1959) ?', 'milliers de papillons', 500, null, false, null, 'bombykol-papillons', 'Université de Bristol (Molecule of the Month)', 'https://www.chm.bris.ac.uk/motm/bombykol/bombykolh.htm', false, 3, 'published'::public.question_status, '2026-10-20', null, '500 000 papillons pour obtenir 6,4 mg de bombykol pur ; structure publiée en 1959 après une vingtaine d’années de recherche (Britannica).'),
('amour-058', 'classique', 'amour', 'number'::public.question_type, 'Lors de son piqué de parade nuptiale, à combien de fois la longueur de son corps par seconde fonce le colibri d’Anna, la vitesse relative la plus élevée connue chez un vertébré ?', 'longueurs de corps par seconde', 385, null, false, null, 'colibri-anna-parade', 'Proc. Royal Society B (Clark, 2009), via Scientific American', 'https://www.scientificamerican.com/blog/news-blog/hummingbirds-outperform-pilots-pull-2009-06-10/', false, 3, 'published'::public.question_status, '2026-10-20', null, 'Vitesse maximale moyenne 27,3 m/s = 385 longueurs de corps/s ; accélération proche de 9 g à la ressource.'),
('amour-059', 'classique', 'amour', 'number'::public.question_type, 'Combien de mois une pieuvre des grands fonds (Graneledone boreopacifica) a-t-elle couvé ses œufs sans les quitter, la plus longue couvaison jamais observée chez un animal ?', 'mois', 53, null, false, null, 'pieuvre-couvaison', 'PLOS ONE / MBARI (2014), via National Geographic', 'https://www.nationalgeographic.com/science/article/octopus-cares-for-her-eggs-for-53-months-then-dies', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Observée à 1 400 m de fond (canyon de Monterey) de 2007 à 2011 : 53 mois, ≈ 160 œufs ; la mère meurt après l’éclosion.'),
('amour-060', 'classique', 'amour', 'number'::public.question_type, 'Combien de tonnes de « cadenas d’amour » ont été retirées du pont des Arts à Paris en 2015, le record pour un pont selon le Guinness ?', 'tonnes', 45, null, false, null, 'pont-des-arts-cadenas', 'Guinness World Records / Ville de Paris', 'https://www.guinnessworldrecords.com/news/2026/4/how-a-paris-bridge-nearly-collapsed-under-45-tonnes-of-love', false, 1, 'published'::public.question_status, '2026-10-20', null, '≈ 45 t, soit 700 000 à 1 million de cadenas (AFP, 1er juin 2015) ; un pan de grille s’était effondré en 2014.'),
('amour-061', 'classique', 'amour', 'number'::public.question_type, 'Jusqu’à combien de jours le manchot empereur mâle jeûne-t-il pendant la saison des amours et la couvaison de son œuf, l’un des plus longs jeûnes du monde des oiseaux ?', 'jours', 115, null, false, null, 'manchot-empereur-jeune', 'Popular Science / Journal of Experimental Biology (2018)', 'https://www.popsci.com/emperor-penguins-fast-snack/', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Jeûne classique ≈ 115 jours (« jusqu’à 4 mois », perte ≈ 20 kg). Une étude suggère que certains mâles se nourrissent avant la ponte. Accepter 110-120.'),
('amour-062', 'classique', 'amour', 'number'::public.question_type, 'Selon le Baromètre santé 2016 de Santé publique France, quel pourcentage des femmes concernées par la contraception utilisaient la pilule, la méthode la plus répandue en France ?', '%', 36.5, null, false, null, 'contraception-pilule', 'Santé publique France (Baromètre santé 2016)', 'https://www.santepubliquefrance.fr/les-actualites/2017/les-francaises-et-la-contraception-premieres-donnees-du-barometre-sante-2016', false, 2, 'published'::public.question_status, '2026-10-20', null, '36,5 % en 2016, contre 40,5 % en 2013 et 45 % en 2010 ; femmes de 15-49 ans concernées par la contraception.'),
('amour-063', 'classique', 'amour', 'number'::public.question_type, 'Selon le zoo national Smithsonian, combien de fois plus petit que sa mère est un bébé panda géant, le plus petit nouveau-né de mammifère par rapport à sa mère (hors marsupiaux) ?', 'fois', 900, null, false, null, 'panda-naissance', 'Smithsonian’s National Zoo', 'https://nationalzoo.si.edu/sites/default/files/documents/giantpandasbackgrounder_2021.08.20.pdf', false, 2, 'published'::public.question_status, '2026-10-20', null, '« 1/900th the size of its mother » ; il pèse 85 à 140 g (3-5 onces). Sujet distinct de « panda-fertilite ».'),
('amour-064', 'classique', 'amour', 'number'::public.question_type, 'Combien de kilomètres certains saumons chinook du Yukon remontent-ils en eau douce pour aller se reproduire, l’une des plus longues migrations de ce type au monde ?', 'km', 3000, null, false, null, 'saumon-yukon', 'NOAA Fisheries (Alaska Fisheries Science Center)', 'https://apps-afsc.fisheries.noaa.gov/quarterly/JFM2015/divrptsABL1.htm', false, 2, 'review'::public.question_status, '2026-10-20', null, 'NOAA : plus de 3 200 km et plus de 60 jours ; Yukon River Panel : 2 960 km ; FishBio : plus de 3 000 km. Accepter 2 900-3 200. À relire : sources divergentes ou chiffre contesté.'),
('amour-065', 'classique', 'amour', 'number'::public.question_type, 'Plus de combien de types de chants différents un moqueur roux mâle peut-il interpréter pour séduire, l’un des plus vastes répertoires connus chez les oiseaux ?', 'chants', 1100, null, false, null, 'moqueur-roux-chants', 'Clark University (Kroodsma et Parker, 1981) / Cornell Lab', 'https://commons.clarku.edu/facultyworks/69', false, 3, 'review'::public.question_status, '2026-10-20', null, 'Étude de terrain (Massachusetts) : plus de 1 100 types de chants. Cornell : « l’un des plus grands répertoires » ; certaines estimations vont jusqu’à 3 000. À relire : sources divergentes ou chiffre contesté.'),
('amour-066', 'classique', 'amour', 'number'::public.question_type, 'Selon le Guinness, combien d’enfants a mis au monde l’épouse du paysan russe Feodor Vassiliev au XVIIIe siècle, le plus grand nombre jamais enregistré pour une mère ?', 'enfants', 69, null, false, null, 'mere-prolifique', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/most-prolific-mother-ever', false, 1, 'review'::public.question_status, '2026-10-20', null, '27 accouchements : 16 paires de jumeaux, 7 triplés, 4 quadruplés (rapport du monastère de Nikolsk, 1782). GWR signale un cas statistiquement improbable. À relire : sources divergentes ou chiffre contesté.'),
('amour-067', 'classique', 'amour', 'number'::public.question_type, 'Combien de fois « je t’aime » est-il écrit, en près de 250 langues, sur le mur des Je t’aime de Montmartre, le plus célèbre mur des amoureux de Paris ?', 'fois', 311, null, false, null, 'mur-je-t-aime', 'Paris je t’aime (office du tourisme de Paris)', 'https://parisjetaime.com/culture/le-mur-des-je-t-aime-p985', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Œuvre de Frédéric Baron et Claire Kito (2000) : 612 carreaux de lave émaillée, ≈ 40 m², 311 « je t’aime ».'),
('amour-068', 'classique', 'amour', 'number'::public.question_type, 'En 2023, un enfant sur combien né en France a été conçu grâce à l’assistance médicale à la procréation (AMP), la proportion la plus élevée jamais atteinte ?', '', 24, null, false, null, 'amp-france', 'Agence de la biomédecine (rapport 2023)', 'https://peps.sante.gouv.fr/actu/2025/25_abm_rapport-2023-amp-dpi_17092025.pdf', false, 2, 'published'::public.question_status, '2026-10-20', null, '≈ 28 440 enfants nés d’une AMP réalisée en 2023, soit 1 sur 24 (1 sur 27 en 2022). Accepter 23-27.'),
('amour-069', 'classique', 'amour', 'number'::public.question_type, 'En quelle année les États-Unis ont-ils autorisé l’Enovid, la toute première pilule contraceptive commercialisée au monde ?', '', 1960, null, true, null, 'pilule-enovid', 'History.com / FDA', 'https://www.history.com/this-day-in-history/may-9/fda-approves-the-pill', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Feu vert de la FDA le 9 mai 1960 (Enovid déjà autorisé en 1957 pour d’autres indications).'),
('amour-070', 'classique', 'amour', 'number'::public.question_type, 'Selon le Guinness, combien de grammes pesait le plus gros œuf jamais pondu par un oiseau vivant, celui d’une autruche en Suède en 2008 ?', 'g', 2589, null, false, null, 'oeuf-autruche-record', 'Guinness World Records', 'https://www.discoverwildlife.com/animal-facts/birds/what-bird-laid-the-biggest-egg', true, 1, 'published'::public.question_status, '2026-10-20', '2027-04-20', '2,589 kg, ferme de Borlänge (Suède), 17 mai 2008 (record GWR repris par BBC Wildlife). Record en vigueur en octobre 2026.'),
('amour-071', 'classique', 'amour', 'number'::public.question_type, 'Selon le Guinness, combien de kilos pesait environ le plus grand nid d’oiseau jamais recensé, bâti par des pygargues à tête blanche en Floride ?', 'kg', 2000, null, false, null, 'nid-pygargue', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/largest-birds-nest', false, 1, 'published'::public.question_status, '2026-10-20', null, 'Nid examiné en 1963 près de St Petersburg : plus de 2 tonnes (4 409 lb), 2,9 m de large, 6 m de profondeur.'),
('amour-072', 'classique', 'amour', 'number'::public.question_type, 'Combien de questions compte le questionnaire du psychologue Arthur Aron (1997), le plus célèbre des tests censés rapprocher deux inconnus jusqu’au coup de cœur ?', 'questions', 36, null, false, null, 'questions-aron', 'Personality and Social Psychology Bulletin (Aron et al., 1997)', 'https://www.cbsnews.com/news/experimental-generation-of-interpersonal-closeness-can-you-fall-in-love-with-36-questions/', false, 1, 'published'::public.question_status, '2026-10-20', null, '36 questions en 3 séries de plus en plus personnelles ; popularisées en 2015 par la chronique « Modern Love » du New York Times.'),
('amour-073', 'classique', 'amour', 'number'::public.question_type, 'Selon l’Insee, au bout de combien d’années de mariage en moyenne un divorce est-il prononcé en France, la durée la plus longue jamais mesurée ?', 'ans', 15, null, false, null, 'divorce-duree-mariage', 'Insee Première n° 1599 (2016)', 'https://www.insee.fr/fr/statistiques/fichier/2121566/ip1599.pdf', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Durée moyenne passée d’environ 12 ans (divorces de 1970) à 15 ans depuis 2008, stable depuis.'),
('amour-074', 'classique', 'amour', 'number'::public.question_type, 'Combien de bébés au maximum un hippocampe mâle, champion des pères qui portent la grossesse, peut-il mettre au monde en une seule fois ?', 'bébés', 2000, null, false, null, 'hippocampe-naissance', 'National Geographic', 'https://www.nationalgeographic.com/pages/article/seahorse-fathers-take-reins-in-childbirth', false, 1, 'review'::public.question_status, '2026-10-20', null, '« As many as 2,000 » selon National Geographic et le Smithsonian ; de 5 à 2 000 selon les espèces. À relire : sources divergentes ou chiffre contesté.'),
('amour-075', 'classique', 'amour', 'number'::public.question_type, 'Selon l’ONU, combien de millions de bébés sont nés dans le monde en 2012, l’année record de toute l’histoire ?', 'millions', 146, null, false, null, 'naissances-monde-record', 'ONU, World Population Prospects 2024 (via Our World in Data)', 'https://ourworldindata.org/grapher/births-and-deaths-projected-to-2100', false, 2, 'published'::public.question_status, '2026-10-20', null, 'WPP 2024 : 146,05 millions en 2012 (maximum de la série 1950-2100) ; 132,1 millions en 2023.'),
('amour-076', 'classique', 'amour', 'number'::public.question_type, 'En quelle année des cardiologues japonais ont-ils décrit pour la première fois le « syndrome du cœur brisé » (takotsubo), la preuve la plus nette qu’un choc émotionnel peut abîmer le cœur ?', '', 1990, null, true, null, 'takotsubo-coeur-brise', 'Revista Portuguesa de Cardiologia', 'https://revportcardiol.org/en-takotsubo-cardiomyopathy-in-cardiology-department-articulo-S217420491200133X', false, 3, 'published'::public.question_status, '2026-10-20', null, 'Première description par Hikaru Sato et coll. en 1990 (5 cas) ; nom tiré d’un piège à poulpe japonais.'),
('amour-077', 'classique', 'amour', 'number'::public.question_type, 'Selon le Guinness, il y a environ combien d’années a été gravé sur une tablette sumérienne le plus vieux poème d’amour connu, dédié au roi Shu-Sin ?', 'ans', 4057, null, false, null, 'poeme-shu-sin', 'Guinness World Records', 'https://www.guinnessworldrecords.com/world-records/oldest-love-poem', false, 3, 'published'::public.question_status, '2026-10-20', null, 'GWR : 2031 av. J.-C. (tablette « Istanbul n° 2461 ») ; World History Encyclopedia : vers 2000 av. J.-C. Énoncé attribué au Guinness ; réponse à lire « av. J.-C. ». Reformulé en « il y a combien d’années » (2026 + 2031) : le pavé du jeu ne saisit pas les années avant J.-C.'),
('amour-078', 'classique', 'amour', 'ranking'::public.question_type, 'Classe ces lois françaises sur le couple et la famille de la plus ancienne à la plus récente', '', null, '[{"label":"Rétablissement du divorce (loi Naquet)","value":1884},{"label":"Autorisation de la contraception (loi Neuwirth)","value":1967},{"label":"Création du PACS","value":1999},{"label":"Ouverture du mariage aux couples de même sexe","value":2013}]'::jsonb, true, null, 'lois-couple-france', 'Encyclopædia Universalis (repères chronologiques)', 'https://www.universalis.fr/encyclopedie/droit-civil-des-personnes-reperes-chronologiques/', false, 1, 'published'::public.question_status, '2026-10-20', null, '27/07/1884, 28/12/1967, 15/11/1999, 17/05/2013.'),
('amour-079', 'classique', 'amour', 'ranking'::public.question_type, 'Classe ces pays de la plus faible à la plus forte part de naissances hors mariage en 2023', '%', null, '[{"label":"Grèce","value":9.7},{"label":"Allemagne","value":33.1},{"label":"Italie","value":40.5},{"label":"France","value":58.5}]'::jsonb, false, null, 'naissances-hors-mariage-europe', 'Eurostat (demo_find)', 'https://ec.europa.eu/eurostat/databrowser/view/demo_find/default/table', false, 2, 'published'::public.question_status, '2026-10-20', null, 'Eurostat 2023 (indicateur NMARPCT) : EL 9,7 ; DE 33,1 ; IT 40,5 ; FR 58,5 ; moyenne UE 41,1. Record UE : Bulgarie 59,7.'),
('amour-080', 'classique', 'amour', 'ranking'::public.question_type, 'Classe ces premières de l’histoire de l’amour de la plus ancienne à la plus récente', '', null, '[{"label":"Première bague de fiançailles en diamant documentée (Maximilien d’Autriche)","value":1477},{"label":"Robe de mariée blanche de la reine Victoria","value":1840},{"label":"Naissance du premier bébé-éprouvette (Louise Brown)","value":1978},{"label":"Premier mariage homosexuel légal au monde (Pays-Bas)","value":2001}]'::jsonb, true, null, 'premieres-amour', 'Wikipédia (Engagement ring) / Royal Collection Trust', 'https://en.wikipedia.org/wiki/Engagement_ring', false, 2, 'published'::public.question_status, '2026-10-20', null, '1477 ; 10/02/1840 ; 25/07/1978 ; 01/04/2001. Victoria a popularisé la robe blanche sans l’inventer.')
